template:
#[derive(Debug, PartialEq)]
enum Signal {
    ⟦variants⟧
}

fn advance(s: Signal) -> Signal {
    match s {
        Signal::Red => Signal::Green,
        Signal::Green => Signal::Yellow,
        ⟦last_arm⟧
    }
}

fn main() {
    println!("{:?}", advance(Signal::Red));
}

tests:
#[test]
fn cycles() {
    assert_eq!(advance(Signal::Red), Signal::Green);
    assert_eq!(advance(Signal::Green), Signal::Yellow);
    assert_eq!(advance(Signal::Yellow), Signal::Red);
}
